-- Ritual cards get their recipes: the monster each summons and the three
-- monsters it sacrifices (see game/engine/ritual.go). A ritual someone has
-- already given an effect through the card admin is left as it is.

UPDATE cards SET data = json_set(data, '$.effect', json('{"op":"ritual","summon":189,"tributes":[{"minDef":2000},{"minDef":2000},{"minDef":2000}]}'), '$.implemented', json('true')) WHERE num = 830 AND json_extract(data, '$.kind') = 'ritual' AND json_extract(data, '$.effect') IS NULL;
